def second_largest_unique_matrix(matrix: list[list[int]]) -> int | None:
    unique = set()
    for row in matrix:
        unique.update(row)
    if len(unique) < 2:
        return None
    return sorted(unique)[-2]

def second_largest_unique_nested(nested: list) -> int | None:
    def flatten(lst):
        for item in lst:
            if isinstance(item, int):
                yield item
            else:
                yield from flatten(item)
    unique = set(flatten(nested))
    if len(unique) < 2:
        return None
    return sorted(unique)[-2]

