import csv

def average_price(csv_path: str) -> float | None:
    total = 0.0
    count = 0
    with open(csv_path, newline='') as f:
        reader = csv.DictReader(f)
        for row in reader:
            val = row.get('price', '').strip()
            if not val:
                continue
            try:
                total += float(val)
                count += 1
            except ValueError:
                continue
    return total / count if count else None

